example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
filename = [tempdir(), 'writer.bin'];
w = protobuf.Writer(schema, 'SensorSample', filename, 'Layout', 'columns');
for k = 1:5
  w.push(struct('timestamp_ms', int64(k * 100 + (1:100)'), 'status', int32(mod((1:100)', 3))));
end
w.close();
C = protobuf.read(schema, 'SensorSample', filename, 'Delimited', true, 'Layout', 'columns');
numel(C.timestamp_ms)
delete(filename);
